arguments.content:
* {
    outline: none;
    border: none;
}

window#waybar {
    background-color: #1a1a2e;
    color: #ffffff;
    font-family: 'JetBrains Mono', monospace;
    font-size: 14px;
    border-radius: 8px 8px 0 0;
}

#workspaces {
    background-color: transparent;
    padding: 0 8px;
}

#workspaces button {
    background-color: #2d2d44;
    color: #8b8ba6;
    border-radius: 6px;
    padding: 4px 12px;
    margin: 0 4px;
    transition: all 0.2s ease;
}

#workspaces button:hover {
    background-color: #3d3d5c;
    color: #ffffff;
}

#workspaces button.focused {
    background-color: #4a9eff;
    color: #ffffff;
    box-shadow: 0 0 8px rgba(74, 158, 255, 0.5);
}

#workspaces button.empty {
    opacity: 0.6;
}

#windowcount {
    background-color: #2d2d44;
    color: #8b8ba6;
    padding: 4px 12px;
    border-radius: 6px;
    margin: 0 8px;
}

#clock {
    background-color: #2d2d44;
    color: #ffffff;
    padding: 4px 16px;
    border-radius: 6px;
    margin: 0 8px;
    font-weight: bold;
}

#pulseaudio {
    background-color: #2d2d44;
    color: #ffffff;
    padding: 4px 12px;
    border-radius: 6px;
    margin: 0 8px;
}

#battery {
    background-color: #2d2d44;
    color: #ffffff;
    padding: 4px 12px;
    border-radius: 6px;
    margin: 0 8px;
}

#network {
    background-color: #2d2d44;
    color: #ffffff;
    padding: 4px 12px;
    border-radius: 6px;
    margin: 0 8px;
}

/* PulseAudio Slider Styles */
#pulseaudio-slider {
    min-width: 100px;
    min-height: 20px;
}

#pulseaudio-slider trough {
    background-color: #3d3d5c;
    border-radius: 4px;
}

#pulseaudio-slider highlight {
    background-color: #4a9eff;
    border-radius: 4px;
}

#pulseaudio-slider slider {
    background-color: #ffffff;
    border-radius: 50%;
    min-width: 12px;
    min-height: 12px;
}

#pulseaudio-slider.muted trough {
    background-color: #3d3d5c;
}

/* Network Styles */
#network label {
    font-size: 14px;
}

/* Clock Styles */
#clock label {
    font-weight: bold;
}

