{
    "layer": "top",
    "position": "top",
    "height": 32,
    "modules-left": ["hyprland/workspaces"],
    "modules-center": ["hyprland/windowcount", "clock"],
    "modules-right": ["pulseaudio", "battery", "network"],
    "hyprland/workspaces": {
        "all-outputs": true,
        "format": "{icon}",
        "separate-outputs": false,
        "on-click": "activate"
    },
    "hyprland/windowcount": {
        "max-length": 20
    },
    "clock": {
        "interval": 60,
        "format": "{:%H:%M}",
        "tooltip-format": "<tt><small>{calendar}</small></tt>",
        "calendar": {
            "mode": "year",
            "mode-mon-col": 3,
            "weeks-pos": "right",
            "first-day-of-week": 1,
            "on-scroll": 1,
            "on-click-right": "mode",
            "format": {
                "months": "<span color='#ffead3'><b>{}</b></span>",
                "days": "<span color='#ecc6d9'><b>{}</b></span>",
                "weeks": "<span color='#99ffdd'><b>W{}</b></span>",
                "weekdays": "<span color='#ffcc66'><b>{}</b></span>",
                "today": "<span color='#ff6699'><b><u>{}</u></b></span>"
            }
        },
        "actions": {
            "on-click-right": "mode",
            "on-click-forward": "tz_up",
            "on-click-backward": "tz_down"
        }
    },
    "pulseaudio": {
        "format-off": "",
        "format-muted": "🔇",
        "format-icons": ["🔉", "🔊"],
        "scroll-step": 5,
        "on-amixer-change": "wpctl set-volume @DEFAULT_AUDIO_SINK@ {volume}%"
    },
    "battery": {
        "states": {
            "warning": 30,
            "critical": 15
        },
        "format-charging": "⚡ {capacity}%",
        "format-full": "🔋 {capacity}%",
        "format-discharging": "🔋 {capacity}%"
    },
    "network": {
        "interface": "eth0",
        "min-width": 150,
        "tooltip-format": "{ifname} | {ipaddr}/{cidr} | {gwaddr}",
        "format-connected": "📶",
        "format-disconnected": "✖"
    }
}
